let
    Source = Table.FromRows(
        {
            // Operational
            {"Operational","Acquisition","New to Title Players", 10},
            {"Operational","Acquisition","New to Franchise Players", 11},

            {"Operational","Engagement","Avg WAU", 20},
            {"Operational","Engagement","Avg % of CWAU", 30},
            {"Operational","Engagement","Avg MAU", 31},
            {"Operational","Engagement","% of Total MAU in Frontline", 40},

            {"Operational","Retention","Avg WoW Retention", 50},
            {"Operational","Retention","Retained Players", 60},

            {"Operational","Monetization","Avg Weekly Conversion Rate", 70},
            {"Operational","Monetization","Avg Weekly ARPS (MTX)", 80},
            {"Operational","Monetization","Avg Weekly ARPU (MTX)", 81},

            // CXO
            {"CXO","","Conversation Volume", 110},
            {"CXO","","Ads and Sponsorship Impressions", 111},
            {"CXO","","Ads and Sponsorship Revenue", 112},
            {"Financial","","ST Units", 130},

            // Financial
            {"Financial","","FG Net Bookings @ Plan FX", 210},
            {"Financial","","Live Service Net Bookings @ Plan FX", 211},
            {"Financial","","Total Net Bookings @ Plan FX", 230},
            {"Financial","","Total Net Bookings @ Actual FX (USD)", 240}

        },
        {"Group","Section","KPI","Order"}
    ),

    #"Changed Types" =
        Table.TransformColumnTypes(
            Source,
            {
                {"Group", type text},
                {"Section", type text},
                {"KPI", type text},
                {"Order", Int64.Type}
            }
        )
in
    #"Changed Types"

